def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    girl_patches = image_patch.find("girl")
    men_patches = image_patch.find("man")

    if not girl_patches:
        return image_patch
    if not men_patches:
        return girl_patches[0]

    girl_center = girl_patches[0].horizontal_center
    men_centers = [man.horizontal_center for man in men_patches]

    closest_men_center = min(men_centers, key=lambda x: abs(x - girl_center))
    closest_men_patch = next((man for man in men_patches if man.horizontal_center == closest_men_center), None)

    if closest_men_patch:
        ground_patches = image_patch.find("ground")
        if ground_patches:
            ground_depth = ground_patches[0].compute_depth()
            if closest_men_patch.compute_depth() <= ground_depth:
                return girl_patches[0]

    return closest_men_patch

