    women = image_patch.find("woman")
    elephants = image_patch.find("elephant")

    if not women or not elephants:
        return image_patch

    elephant_trunk_patches = []
    for elephant in elephants:
        trunk = elephant.crop(elephant.left + elephant.width // 4, elephant.lower, elephant.right - elephant.width // 4, elephant.upper)
        trunk_patches = trunk.find("trunk")
        elephant_trunk_patches.extend(trunk_patches)

    if not elephant_trunk_patches:
        return image_patch

    hugs = []
    for woman in women:
        for trunk in elephant_trunk_patches:
            if distance(woman, trunk) < min(woman.width, woman.height, trunk.width, trunk.height):
                hugs.append((woman, trunk))

    if not hugs:
        return image_patch

    hug_distances = [(hug[0].horizontal_center - hug[1].horizontal_center, hug) for hug in hugs]
    hug_distances.sort()

    return hug_distances[0][1][0]

