def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    fruit_patches = image_patch.find("fruit")
    if not fruit_patches: return image_patch

    # Sort fruits by their horizontal center
    fruit_patches.sort(key=lambda f: f.horizontal_center)

    # Select the middle fruit
    middle_fruit = fruit_patches[len(fruit_patches) // 2]

    # Find the side of the fruit that is facing away from the shot
    if middle_fruit.left < middle_fruit.right:
        facing_side = "right"
    else:
        facing_side = "left"

    # Crop the fruit to show only the side facing away
    if facing_side == "right":
        return middle_fruit.crop(middle_fruit.horizontal_center, middle_fruit.lower, middle_fruit.right, middle_fruit.upper)
    else:
        return middle_fruit.crop(middle_fruit.left, middle_fruit.lower, middle_fruit.horizontal_center, middle_fruit.upper)

